INSERT INTO `roles` (`id`, `codigo`, `nombre`, `descripcion`) VALUES
(1, 'ADMIN', 'Administrador General OTIC', 'Control total de usuarios, SLAs y catálogo'),
(2, 'SUPERVISOR', 'Jefe / Supervisor OTIC', 'Asignación de tickets, monitoreo SLA y reportes'),
(3, 'TECNICO', 'Especialista en Soporte Técnico', 'Atención y resolución técnica de soporte a usuarios y equipos de cómputo'),
(4, 'SOLICITANTE', 'Usuario Final UNALM', 'Alumnos, docentes y administrativos que registran requerimientos'),
(5, 'MESA_AYUDA', 'Mesa de Ayuda OTIC', 'Triage, derivación y gestión de colas de tickets OTIC'),
(6, 'MESA_AYUDA_SG', 'Mesa de Ayuda Servicios Generales', 'Triage, derivación y gestión de colas de tickets de Servicios Generales e Infraestructura'),
(7, 'TECNICO_SG', 'Especialista Servicios Generales', 'Atención y resolución técnica en rubros de mantenimiento e infraestructura (ROF UNALM)'),
(8, 'SUPERVISOR_SG', 'Supervisor Servicios Generales', 'Jefatura y supervisión de la Unidad de Servicios Generales y Mantenimiento'),
(9, 'ESPECIALISTA_REDES', 'Especialista en Redes', 'Atención y resolución técnica de incidencias en conectividad, cableado, fibra óptica y switches'),
(10, 'ESPECIALISTA_DESARROLLO', 'Especialista en Desarrollo', 'Atención y resolución técnica en sistemas, software, bases de datos y portales web');
INSERT INTO `configuracion_sistema` (`id`, `clave`, `valor`, `descripcion`) VALUES
(1, 'asignacion_automatica_inmediata', 'false', 'Derivación automática a técnico por defecto al crear ticket');
INSERT INTO `categorias_servicio` (`id`, `nombre`, `codigo`, `descripcion`, `icono`, `orden`, `modulo`, `sla_horas_respuesta`, `sla_horas_resolucion`, `tecnico_defecto_id`, `activo`) VALUES
(1, 'Infraestructura y Red Wi-Fi', 'NET_WIFI', 'Problemas con conectividad Eduroam, Red UNALM corporativa, puntos de acceso y puntos de red en aulas u oficinas.', 'Wifi', 0, 'OTIC', 2, 8, 3, 1),
(2, 'Sistemas Académicos (SIRA / Aula Virtual)', 'SYS_ACAD', 'Incidencias con notas, matrícula, Aulas Virtuales Moodle, restablecimiento de accesos académicos.', 'GraduationCap', 0, 'OTIC', 2, 12, 4, 1),
(3, 'Correo Institucional y Cuentas', 'AUTH_MAIL', 'Reset de contraseña corporativa @lamolina.edu.pe, creación de cuentas para personal o nuevos alumnos.', 'Mail', 0, 'OTIC', 4, 12, 4, 1),
(4, 'Soporte Hardware y Periféricos', 'HW_SUPP', 'Mantenimiento preventivo/correctivo de computadoras, impresoras, proyectores multimedia en laboratorios u oficinas.', 'Monitor', 0, 'OTIC', 4, 24, 3, 1),
(5, 'Firma Digital y Certificados', 'DIG_SIGN', 'Instalación de token de firma digital RENIEC/Refirma, certificados SSL y software de gestión institucional.', 'FileCheck', 0, 'OTIC', 4, 16, 4, 1),
(6, 'Obras Civiles, Albañilería y Cerrajería', 'SG_INFRA', 'Reparación de cerraduras, puertas, ventanas, muros, resanes, techos, baldosas y obras civiles menores en pabellones y aulas.', 'Building2', 1, 'SERVICIOS_GENERALES', 3, 24, NULL, 1),
(7, 'Mantenimiento Eléctrico e Iluminación', 'SG_ELEC', 'Incidencias con fluido eléctrico, cortocircuitos, cambio de luminarias en aulas/campus, tableros eléctricos y tomacorrientes.', 'Zap', 2, 'SERVICIOS_GENERALES', 2, 12, NULL, 1),
(8, 'Mantenimiento Sanitario y Gasfitería', 'SG_SAN', 'Fugas de agua, desatoro de desagües, reparación de fluxómetros, grifería, inodoros, bombas de presión y tuberías en servicios higiénicos.', 'Wrench', 3, 'SERVICIOS_GENERALES', 2, 12, NULL, 1),
(9, 'Climatización, Ventilación y Refrigeración', 'SG_CLIMA', 'Mantenimiento de sistemas de aire acondicionado, extractores de aire en laboratorios y cámaras de conservación.', 'Cpu', 4, 'SERVICIOS_GENERALES', 4, 24, NULL, 1),
(10, 'Mantenimiento de Áreas Verdes y Forestación', 'SG_JARDIN', 'Poda de árboles de riesgo, riego de jardines, limpieza de bermas y conservación de áreas forestales del campus universitario.', 'Flower2', 5, 'SERVICIOS_GENERALES', 6, 48, NULL, 1),
(11, 'Limpieza, Saneamiento y Residuos', 'SG_LIMPIEZA', 'Servicio de fumigación, desinfección ambiental, acopio y retiro de residuos sólidos especiales en facultades u oficinas.', 'Trash2', 6, 'SERVICIOS_GENERALES', 4, 24, NULL, 1),
(12, 'Transporte, Mudanza Interna y Apoyo Logístico', 'SG_TRANS', 'Traslado de carpetas, escritorios, mobiliario para eventos institucionales, exámenes de admisión o ceremonias protocolares.', 'Truck', 7, 'SERVICIOS_GENERALES', 6, 24, NULL, 1);
