-- =============================================================================
-- SISTEMA DE MESA DE AYUDA IN-HOUSE - OTIC & SERVICIOS GENERALES UNALM
-- ESQUEMA COMPLETO DE BASE DE DATOS Y SEEDERS INSTITUCIONALES (ITIL v4 READY)
-- Base de Datos: mesaayuda_test_db | Motor: MySQL 8.0+ / MariaDB 10.5+
-- =============================================================================

CREATE DATABASE IF NOT EXISTS `mesaayuda_test_db` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `mesaayuda_test_db`;

-- Desactivar temporalmente verificaciones de claves foráneas para recreación segura
SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `solicitudes_cuenta_ad`;
DROP TABLE IF EXISTS `materiales_movimientos_sg`;
DROP TABLE IF EXISTS `materiales_inventario_sg`;
DROP TABLE IF EXISTS `hallazgos_inspeccion`;
DROP TABLE IF EXISTS `inspecciones_infraestructura`;
DROP TABLE IF EXISTS `configuracion_sistema`;
DROP TABLE IF EXISTS `logs_auditoria`;
DROP TABLE IF EXISTS `encuestas_satisfaccion`;
DROP TABLE IF EXISTS `adjuntos`;
DROP TABLE IF EXISTS `comentarios_ticket`;
DROP TABLE IF EXISTS `tickets`;
DROP TABLE IF EXISTS `categorias_servicio`;
DROP TABLE IF EXISTS `usuarios`;
DROP TABLE IF EXISTS `roles`;

SET FOREIGN_KEY_CHECKS = 1;

-- =============================================================================
-- 1. TABLA ROLES (RBAC MULTIMÓDULO: OTIC Y SERVICIOS GENERALES)
-- =============================================================================
CREATE TABLE `roles` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `codigo` VARCHAR(30) NOT NULL UNIQUE,
  `nombre` VARCHAR(100) NOT NULL,
  `descripcion` VARCHAR(255) NULL,
  `creado_en` DATETIME DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- =============================================================================
-- 2. TABLA USUARIOS (Comunidad Institucional UNALM @lamolina.edu.pe)
-- =============================================================================
CREATE TABLE `usuarios` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `nombres` VARCHAR(100) NOT NULL,
  `apellidos` VARCHAR(100) NOT NULL,
  `email` VARCHAR(150) NOT NULL UNIQUE,
  `password_hash` VARCHAR(255) NOT NULL,
  `rol_id` INT NOT NULL,
  `facultad_dependencia` VARCHAR(150) NOT NULL DEFAULT 'OTIC',
  `ubicacion_referencia` VARCHAR(255) NULL,
  `cargo` VARCHAR(150) NULL,
  `debe_cambiar_password` TINYINT(1) NOT NULL DEFAULT 0,
  `correo_pendiente` TINYINT(1) NOT NULL DEFAULT 0,
  `especialidad` VARCHAR(150) NULL,
  `telefono` VARCHAR(30) NULL,
  `anexo` VARCHAR(50) NULL,
  `foto_perfil` VARCHAR(255) NULL,
  `estado` ENUM('ACTIVO', 'INACTIVO', 'BLOQUEADO') DEFAULT 'ACTIVO',
  `ultimo_acceso` DATETIME NULL,
  `creado_en` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `actualizado_en` DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT `fk_usuarios_roles` FOREIGN KEY (`rol_id`) REFERENCES `roles` (`id`) ON UPDATE CASCADE,
  INDEX `idx_usuarios_email` (`email`),
  INDEX `idx_usuarios_rol` (`rol_id`),
  INDEX `idx_usuarios_estado` (`estado`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- =============================================================================
-- 3. TABLA CATEGORIAS DE SERVICIO (CATÁLOGO ITIL v4: OTIC Y SERVICIOS GENERALES)
-- =============================================================================
CREATE TABLE `categorias_servicio` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `nombre` VARCHAR(120) NOT NULL,
  `codigo` VARCHAR(50) NOT NULL UNIQUE,
  `descripcion` TEXT NULL,
  `icono` VARCHAR(50) DEFAULT 'HelpCircle',
  `orden` INT NOT NULL DEFAULT 0,
  `modulo` ENUM('OTIC', 'SERVICIOS_GENERALES') NOT NULL DEFAULT 'OTIC',
  `sla_horas_respuesta` INT NOT NULL DEFAULT 4,
  `sla_horas_resolucion` INT NOT NULL DEFAULT 24,
  `tecnico_defecto_id` INT NULL,
  `activo` TINYINT(1) DEFAULT 1,
  `creado_en` DATETIME DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT `fk_categorias_tecnico` FOREIGN KEY (`tecnico_defecto_id`) REFERENCES `usuarios` (`id`) ON DELETE SET NULL,
  INDEX `idx_categorias_activo` (`activo`),
  INDEX `idx_categorias_modulo` (`modulo`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- =============================================================================
-- 4. TABLA CONFIGURACIÓN DEL SISTEMA
-- =============================================================================
CREATE TABLE `configuracion_sistema` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `clave` VARCHAR(100) NOT NULL UNIQUE,
  `valor` VARCHAR(255) NOT NULL,
  `descripcion` VARCHAR(255) NULL,
  `actualizado_en` DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- =============================================================================
-- 5. TABLA INSPECCIONES DE INFRAESTRUCTURA (PREVENTIVO SIGI UNALM)
-- =============================================================================
CREATE TABLE `inspecciones_infraestructura` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `codigo` VARCHAR(50) NOT NULL UNIQUE,
  `fecha_registro` DATETIME NOT NULL,
  `edificio` VARCHAR(150) NOT NULL,
  `area` VARCHAR(150) NOT NULL,
  `inspector_nombre` VARCHAR(150) NOT NULL,
  `responsable_area` VARCHAR(150) NULL,
  `soporte_tecnico` VARCHAR(150) NULL,
  `observaciones_generales` TEXT NULL,
  `total_evaluados` INT DEFAULT 0,
  `total_criticos` INT DEFAULT 0,
  `tickets_generados` INT DEFAULT 0,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  INDEX `idx_insp_fecha` (`fecha_registro`),
  INDEX `idx_insp_edificio` (`edificio`),
  INDEX `idx_insp_area` (`area`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- =============================================================================
-- 6. TABLA HALLAZGOS DE INSPECCIÓN (DETALLES Y VINCULACIÓN A TICKETS)
-- =============================================================================
CREATE TABLE `hallazgos_inspeccion` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `inspeccion_id` INT NOT NULL,
  `categoria_codigo` VARCHAR(10) NOT NULL,
  `categoria_nombre` VARCHAR(100) NOT NULL,
  `item_codigo` VARCHAR(20) NOT NULL,
  `item_nombre` VARCHAR(150) NOT NULL,
  `estado_calificacion` ENUM('CRITICO', 'MANTENIMIENTO', 'BUENO', 'EXCELENTE', 'NO_APLICA') NOT NULL DEFAULT 'BUENO',
  `calificacion_num` INT DEFAULT 3,
  `observacion` TEXT NULL,
  `accion_sugerida` VARCHAR(255) NULL,
  `prioridad` ENUM('BAJA', 'MEDIA', 'ALTA', 'CRITICA') NOT NULL DEFAULT 'MEDIA',
  `categoria_sg_sugerida` VARCHAR(50) NULL,
  `ticket_id` INT NULL,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT `fk_hallazgo_inspeccion` FOREIGN KEY (`inspeccion_id`) REFERENCES `inspecciones_infraestructura` (`id`) ON DELETE CASCADE,
  INDEX `idx_hallazgo_estado` (`estado_calificacion`),
  INDEX `idx_hallazgo_ticket` (`ticket_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- =============================================================================
-- 7. TABLA TICKETS (INCIDENTES Y SOLICITUDES ITIL / SERVICIOS GENERALES)
-- =============================================================================
CREATE TABLE `tickets` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `codigo_correlativo` VARCHAR(30) NOT NULL UNIQUE,
  `modulo` ENUM('OTIC', 'SERVICIOS_GENERALES') NOT NULL DEFAULT 'OTIC',
  `titulo` VARCHAR(200) NOT NULL,
  `descripcion` TEXT NOT NULL,
  `tipo` ENUM('INCIDENTE', 'SOLICITUD_SERVICIO', 'MANTENIMIENTO_PREVENTIVO', 'MANTENIMIENTO_CORRECTIVO') NOT NULL DEFAULT 'INCIDENTE',
  `prioridad` ENUM('BAJA', 'MEDIA', 'ALTA', 'CRITICA') NOT NULL DEFAULT 'MEDIA',
  `impacto` ENUM('BAJO', 'MEDIO', 'ALTO') NOT NULL DEFAULT 'MEDIO',
  `urgencia` ENUM('BAJA', 'MEDIA', 'ALTA', 'CRITICA') NOT NULL DEFAULT 'MEDIA',
  `complejidad` ENUM('BAJA', 'MEDIA', 'ALTA', 'COMPLEJA') NOT NULL DEFAULT 'BAJA',
  `estado` ENUM('REPORTADO', 'EVALUACION_INSPECCION', 'ESPERA_MATERIALES', 'ESPERA_MATERIALES_SOLICITANTE', 'ASIGNADO', 'EN_EJECUCION', 'RESUELTO', 'NUEVO', 'EN_PROCESO', 'PENDIENTE_USUARIO', 'CERRADO', 'REABIERTO', 'OBSERVADO') NOT NULL DEFAULT 'REPORTADO',
  `solicitante_id` INT NOT NULL,
  `tecnico_id` INT NULL,
  `categoria_id` INT NOT NULL,
  `ubicacion_oficina` VARCHAR(150) NULL,
  `canal_origen` ENUM('PORTAL_WEB', 'CORREO', 'TELEFONO', 'PRESENCIAL', 'INSPECCION_SIGI') NOT NULL DEFAULT 'PORTAL_WEB',
  `fecha_apertura` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `fecha_primera_respuesta` DATETIME NULL,
  `fecha_limite_respuesta` DATETIME NULL,
  `fecha_limite_resolucion` DATETIME NULL,
  `fecha_resolucion` DATETIME NULL,
  `fecha_cierre` DATETIME NULL,
  `cumplio_sla_respuesta` TINYINT(1) DEFAULT 1,
  `cumplio_sla_resolucion` TINYINT(1) DEFAULT 1,
  `solucion_detalle` TEXT NULL,
  `contacto_local` VARCHAR(150) NULL,
  `horario_acceso` VARCHAR(150) NULL,
  `subtipo_intervencion` VARCHAR(60) NULL,
  `datos_vehiculares` VARCHAR(150) NULL,
  `materiales_usados` TEXT NULL,
  `materiales_sobrantes` TEXT NULL,
  `referencia_ubicacion` VARCHAR(255) NULL,
  `es_equipo` TINYINT(1) NOT NULL DEFAULT 0,
  `numero_inventario` VARCHAR(100) NULL,
  `inspeccion_id` INT NULL,
  `hallazgo_id` INT NULL,
  `creado_en` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `actualizado_en` DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT `fk_tickets_solicitante` FOREIGN KEY (`solicitante_id`) REFERENCES `usuarios` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_tickets_tecnico` FOREIGN KEY (`tecnico_id`) REFERENCES `usuarios` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_tickets_categoria` FOREIGN KEY (`categoria_id`) REFERENCES `categorias_servicio` (`id`) ON DELETE RESTRICT,
  INDEX `idx_tickets_codigo` (`codigo_correlativo`),
  INDEX `idx_tickets_modulo` (`modulo`),
  INDEX `idx_tickets_estado` (`estado`),
  INDEX `idx_tickets_solicitante` (`solicitante_id`),
  INDEX `idx_tickets_tecnico` (`tecnico_id`),
  INDEX `idx_tickets_categoria` (`categoria_id`),
  INDEX `idx_tickets_prioridad` (`prioridad`),
  INDEX `idx_tickets_fecha_apertura` (`fecha_apertura`),
  INDEX `idx_tickets_numero_inventario` (`numero_inventario`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- =============================================================================
-- 7.1 TABLA ASIGNACIONES MÚLTIPLES DE TÉCNICOS (CASOS DE ALTA COMPLEJIDAD OTIC)
-- =============================================================================
CREATE TABLE IF NOT EXISTS `ticket_tecnicos` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `ticket_id` INT NOT NULL,
  `tecnico_id` INT NOT NULL,
  `rol_asignacion` ENUM('PRINCIPAL', 'APOYO') NOT NULL DEFAULT 'APOYO',
  `creado_en` DATETIME DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY `uk_ticket_tecnico` (`ticket_id`, `tecnico_id`),
  CONSTRAINT `fk_ticket_tecnicos_ticket` FOREIGN KEY (`ticket_id`) REFERENCES `tickets` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_ticket_tecnicos_tecnico` FOREIGN KEY (`tecnico_id`) REFERENCES `usuarios` (`id`) ON DELETE CASCADE,
  INDEX `idx_tt_ticket` (`ticket_id`),
  INDEX `idx_tt_tecnico` (`tecnico_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- =============================================================================
-- 8. TABLA COMENTARIOS Y CHAT DE TICKET (NOTAS INTERNAS vs CHAT PÚBLICO)
-- =============================================================================
CREATE TABLE `comentarios_ticket` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `ticket_id` INT NOT NULL,
  `usuario_id` INT NOT NULL,
  `mensaje` TEXT NOT NULL,
  `es_nota_interna` TINYINT(1) NOT NULL DEFAULT 0,
  `creado_en` DATETIME DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT `fk_comentarios_ticket` FOREIGN KEY (`ticket_id`) REFERENCES `tickets` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_comentarios_usuario` FOREIGN KEY (`usuario_id`) REFERENCES `usuarios` (`id`),
  INDEX `idx_comentarios_ticket_id` (`ticket_id`),
  INDEX `idx_comentarios_es_nota_interna` (`es_nota_interna`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- =============================================================================
-- 9. TABLA ADJUNTOS DE ARCHIVOS (/uploads/)
-- =============================================================================
CREATE TABLE `adjuntos` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `ticket_id` INT NOT NULL,
  `comentario_id` INT NULL,
  `nombre_original` VARCHAR(255) NOT NULL,
  `nombre_guardado` VARCHAR(255) NOT NULL,
  `ruta_servidor` VARCHAR(500) NOT NULL,
  `tamano_bytes` BIGINT NOT NULL,
  `mime_type` VARCHAR(100) NOT NULL,
  `subido_por_id` INT NOT NULL,
  `creado_en` DATETIME DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT `fk_adjuntos_ticket` FOREIGN KEY (`ticket_id`) REFERENCES `tickets` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_adjuntos_comentario` FOREIGN KEY (`comentario_id`) REFERENCES `comentarios_ticket` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_adjuntos_usuario` FOREIGN KEY (`subido_por_id`) REFERENCES `usuarios` (`id`),
  INDEX `idx_adjuntos_ticket_id` (`ticket_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- =============================================================================
-- 10. TABLA ENCUESTAS DE SATISFACCIÓN (CALIDAD ITIL)
-- =============================================================================
CREATE TABLE `encuestas_satisfaccion` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `ticket_id` INT NOT NULL UNIQUE,
  `tecnico_id` INT NULL,
  `solicitante_id` INT NULL,
  `puntuacion` TINYINT NOT NULL CHECK (`puntuacion` BETWEEN 1 AND 5),
  `comentario` TEXT NULL,
  `fecha_encuesta` DATETIME DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT `fk_encuestas_ticket` FOREIGN KEY (`ticket_id`) REFERENCES `tickets` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- =============================================================================
-- 11. TABLA LOGS DE AUDITORÍA (TRAZABILIDAD Y REGISTRO FORENSE)
-- =============================================================================
CREATE TABLE `logs_auditoria` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `ticket_id` INT NOT NULL,
  `usuario_id` INT NULL,
  `accion` VARCHAR(100) NOT NULL,
  `campo_modificado` VARCHAR(100) NULL,
  `valor_anterior` TEXT NULL,
  `valor_nuevo` TEXT NULL,
  `ip_origen` VARCHAR(45) NULL,
  `fecha` DATETIME DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT `fk_auditoria_ticket` FOREIGN KEY (`ticket_id`) REFERENCES `tickets` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_auditoria_usuario` FOREIGN KEY (`usuario_id`) REFERENCES `usuarios` (`id`) ON DELETE SET NULL,
  INDEX `idx_auditoria_ticket_id` (`ticket_id`),
  INDEX `idx_auditoria_fecha` (`fecha`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- =============================================================================
-- 12. TABLA INVENTARIO DE MATERIALES (TALLERES DE SERVICIOS GENERALES)
-- =============================================================================
CREATE TABLE `materiales_inventario_sg` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `codigo` VARCHAR(50) NOT NULL UNIQUE,
  `nombre` VARCHAR(255) NOT NULL,
  `categoria_taller` VARCHAR(100) NOT NULL,
  `unidad_medida` VARCHAR(50) NOT NULL DEFAULT 'Unidad (und)',
  `stock_actual` DECIMAL(10,2) NOT NULL DEFAULT 0.00,
  `stock_minimo` DECIMAL(10,2) NOT NULL DEFAULT 5.00,
  `ubicacion_almacen` VARCHAR(150) NULL,
  `precio_unitario_estimado` DECIMAL(10,2) DEFAULT 0.00,
  `creado_en` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `actualizado_en` DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- =============================================================================
-- 13. TABLA MOVIMIENTOS DE MATERIALES (KARDEX / TRAZABILIDAD ORDENES DE TRABAJO)
-- =============================================================================
CREATE TABLE `materiales_movimientos_sg` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `material_id` INT NOT NULL,
  `tipo_movimiento` ENUM('ENTRADA_COMPRA', 'ENTRADA_DEVOLUCION', 'SALIDA_OT', 'SALIDA_AJUSTE') NOT NULL,
  `cantidad` DECIMAL(10,2) NOT NULL,
  `stock_anterior` DECIMAL(10,2) NOT NULL,
  `stock_nuevo` DECIMAL(10,2) NOT NULL,
  `ticket_id` INT NULL,
  `orden_trabajo_codigo` VARCHAR(60) NULL,
  `usuario_id` INT NOT NULL,
  `usuario_nombre` VARCHAR(150) NULL,
  `motivo` VARCHAR(255) NULL,
  `observaciones` TEXT NULL,
  `fecha` DATETIME DEFAULT CURRENT_TIMESTAMP,
  KEY `fk_mov_material` (`material_id`),
  CONSTRAINT `fk_mov_material` FOREIGN KEY (`material_id`) REFERENCES `materiales_inventario_sg` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- =============================================================================
-- 14. TABLA SOLICITUDES DE ALTA DE CUENTA EN DIRECTORIO ACTIVO (REDES)
-- =============================================================================
CREATE TABLE IF NOT EXISTS `solicitudes_cuenta_ad` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `nombre_completo` VARCHAR(255) NOT NULL,
  `dni` VARCHAR(20) NOT NULL,
  `condicion` VARCHAR(100) NOT NULL,
  `email` VARCHAR(150) NOT NULL,
  `facultad_dependencia` VARCHAR(255) NOT NULL,
  `celular` VARCHAR(30) NOT NULL,
  `anexo` VARCHAR(20) NULL,
  `estado` ENUM('PENDIENTE', 'CREADO', 'RECHAZADO') NOT NULL DEFAULT 'PENDIENTE',
  `creado_en` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  INDEX `idx_solicitudes_dni` (`dni`),
  INDEX `idx_solicitudes_email` (`email`),
  INDEX `idx_solicitudes_estado` (`estado`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


